/* The translated function table of the 1989 build (a second build of the engine has its own,
 * ant_table.h). The table is data; rc_lookup/rc_containing search whichever program rc_active
 * names, so a second build needs no second pair of searches. */
#ifndef ICFTD_RECOMP_FN_TABLE_H
#define ICFTD_RECOMP_FN_TABLE_H

#include "cpu.h"

/* Sorted by address and terminated by an entry with fn == 0 (generated by the emitter). */
extern const rc_entry rc_functions[];
extern const unsigned rc_functionCount;

/* The 1989 build as the runtime sees it: its table, A4, entry and save file (generated). */
extern const rc_program rc_engine;

/* The translated function for `addr`, or 0. Case-insensitive about nothing: addresses are exact. */
rc_fn rc_lookup(u32 addr);

/* The function whose [addr,end) contains `addr`, or 0. A jsr/jmp can land in the middle of a
 * function (the engine's own opcode tables do), so callers use this before falling back. */
const rc_entry *rc_containing(u32 addr);

/* Declares `fn_<addr>` so the table does not need a header per function. */
#define RC_DECL(addr) extern void fn_##addr(cpu_t *c, rt_machine *m)

#endif
